import{_ as t,o,c as d,a3 as s}from"./chunks/framework.vDgOMd_y.js";const u=JSON.parse('{"title":"Custom Themes","description":"","frontmatter":{},"headers":[],"relativePath":"en/customization/themes.md","filePath":"en/customization/themes.md"}'),a={name:"en/customization/themes.md"};function i(n,e,l,c,r,h){return o(),d("div",null,[...e[0]||(e[0]=[s(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /kimiteam/docs/en/customization/themes.md for this page in Markdown format</div><h1 id="custom-themes" tabindex="-1">Custom Themes <a class="header-anchor" href="#custom-themes" aria-label="Permalink to &quot;Custom Themes&quot;">​</a></h1><p>Kimi Code CLI can use a built-in color scheme or a custom JSON theme file. Custom files live in the themes directory and appear in <code>/theme</code> alongside the built-in choices.</p><h2 id="built-in-color-tokens" tabindex="-1">Built-in color tokens <a class="header-anchor" href="#built-in-color-tokens" aria-label="Permalink to &quot;Built-in color tokens&quot;">​</a></h2><p>Custom themes can override the tokens below. The <code>dark</code> and <code>light</code> columns show the built-in values; <code>auto</code> resolves to one of those palettes at startup, and falls back to <code>dark</code> when terminal background detection is unavailable.</p><table tabindex="0"><thead><tr><th>Token</th><th><code>dark</code></th><th><code>light</code></th><th>What it controls</th></tr></thead><tbody><tr><td><code>primary</code></td><td><code>#4FA8FF</code></td><td><code>#1565C0</code></td><td>The most-used color. Links, inline code, the selected item in nearly every dialog, the focused editor border, Plan/&quot;running&quot; badges, spinners</td></tr><tr><td><code>accent</code></td><td><code>#5BC0BE</code></td><td><code>#00838F</code></td><td>Secondary highlight. Approval <code>▶</code> prefix, device-code box, image placeholder, BTW / queue panes, registry import</td></tr><tr><td><code>text</code></td><td><code>#E0E0E0</code></td><td><code>#1A1A1A</code></td><td>Body text. Dialog bodies, todo titles, footer model label, Markdown headings, assistant/tool message bullets, list bullets</td></tr><tr><td><code>textStrong</code></td><td><code>#F5F5F5</code></td><td><code>#1A1A1A</code></td><td>Emphasized / bold text. Input dialogs, status messages</td></tr><tr><td><code>textDim</code></td><td><code>#888888</code></td><td><code>#454545</code></td><td>Secondary, dimmed text. Thinking, hints, descriptions, completed todos, Markdown quotes, footer status bar</td></tr><tr><td><code>textMuted</code></td><td><code>#6B6B6B</code></td><td><code>#5F5F5F</code></td><td>Faintest text. Counters, scroll info, descriptions, Markdown link URLs, code-block borders</td></tr><tr><td><code>border</code></td><td><code>#5A5A5A</code></td><td><code>#737373</code></td><td>Pane and editor borders, Markdown horizontal rule</td></tr><tr><td><code>borderFocus</code></td><td><code>#E8A838</code></td><td><code>#92660A</code></td><td>Focus / attention border, currently only the approval panel</td></tr><tr><td><code>success</code></td><td><code>#4EC87E</code></td><td><code>#0E7A38</code></td><td>Success state. <code>✓</code>, &quot;enabled&quot;, completed</td></tr><tr><td><code>warning</code></td><td><code>#E8A838</code></td><td><code>#92660A</code></td><td>Warning state. auto/yolo badges, stale markers, Plan mode hint</td></tr><tr><td><code>error</code></td><td><code>#E85454</code></td><td><code>#B91C1C</code></td><td>Error state. Error messages, failed tool output</td></tr><tr><td><code>diffAdded</code></td><td><code>#4EC87E</code></td><td><code>#0E7A38</code></td><td>Diff added lines</td></tr><tr><td><code>diffRemoved</code></td><td><code>#E85454</code></td><td><code>#B91C1C</code></td><td>Diff removed lines</td></tr><tr><td><code>diffAddedStrong</code></td><td><code>#7AD99B</code></td><td><code>#0E7A38</code></td><td>Diff intra-line changed words, added and bold</td></tr><tr><td><code>diffRemovedStrong</code></td><td><code>#F08585</code></td><td><code>#B91C1C</code></td><td>Diff intra-line changed words, removed and bold</td></tr><tr><td><code>diffGutter</code></td><td><code>#6B6B6B</code></td><td><code>#737373</code></td><td>Diff line-number gutter</td></tr><tr><td><code>diffMeta</code></td><td><code>#888888</code></td><td><code>#5F5F5F</code></td><td>Diff meta / hunk headers</td></tr><tr><td><code>roleUser</code></td><td><code>#FFCB6B</code></td><td><code>#9A4A00</code></td><td>User message bullet and text, skill-activation name</td></tr><tr><td><code>shellMode</code></td><td><code>#BD93F9</code></td><td><code>#7C3AED</code></td><td>Shell mode (<code>!</code>) prompt, editor border, and the echoed <code>$ command</code> line</td></tr></tbody></table><h2 id="use-the-custom-theme-skill" tabindex="-1">Use the custom-theme skill <a class="header-anchor" href="#use-the-custom-theme-skill" aria-label="Permalink to &quot;Use the custom-theme skill&quot;">​</a></h2><p>You do not need to write the JSON by hand. Run the built-in <code>/custom-theme [extra text]</code> skill command to enter the custom-theme workflow; the skill can choose colors, write the file under <code>~/.kimi-code/themes/</code>, validate the hex values, and tell you how to apply it.</p><p>Example invocations:</p><ul><li><code>/custom-theme Create a warm dark theme with amber accents.</code></li><li><code>/custom-theme Make a light theme based on Solarized, but keep errors easy to see.</code></li><li><code>/custom-theme Tweak my ember theme so diffs have higher contrast.</code></li></ul><p>After activation, the skill usually asks whether you want a light or dark base, what mood or palette you prefer, and whether you have exact colors to include. If you use it to edit an existing theme, make sure it reads and backs up the file before overwriting it.</p><h2 id="create-a-theme" tabindex="-1">Create a theme <a class="header-anchor" href="#create-a-theme" aria-label="Permalink to &quot;Create a theme&quot;">​</a></h2><p>Add a <code>.json</code> file to the themes directory:</p><ul><li><code>~/.kimi-code/themes/</code></li><li>or <code>$KIMI_CODE_HOME/themes/</code> when the <code>KIMI_CODE_HOME</code> environment variable is set</li></ul><p>Create the directory if it does not exist. <strong>The filename is the theme name</strong>: <code>ember.json</code> appears in <code>/theme</code> as <code>Custom: ember</code>.</p><p>A minimal theme only sets the colors you want to change; the rest fall back to the <strong>base palette</strong> (<code>dark</code> by default):</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ember&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;colors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#83A598&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;accent&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#FE8019&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Fields:</p><ul><li><code>name</code> (required): the theme identifier.</li><li><code>displayName</code> (optional): a human-readable name.</li><li><code>base</code> (optional): the built-in palette that unspecified tokens inherit — <code>&quot;dark&quot;</code> (default) or <code>&quot;light&quot;</code>. Set <code>&quot;base&quot;: &quot;light&quot;</code> when you are building a <strong>light</strong> theme so the tokens you leave out stay readable on a light background (otherwise they fall back to the dark palette).</li><li><code>colors</code> (optional): the color tokens to override, each a 6-digit hex value (e.g. <code>#FE8019</code>).</li></ul><p>Use the token names from <a href="#built-in-color-tokens">Built-in color tokens</a>. Any token you omit falls back to the selected base palette, so partial themes are fine:</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;just-blue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;colors&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;primary&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#3B82F6&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;roleUser&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;#3B82F6&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><h2 id="select-a-theme" tabindex="-1">Select a theme <a class="header-anchor" href="#select-a-theme" aria-label="Permalink to &quot;Select a theme&quot;">​</a></h2><p>Two ways:</p><ol><li><p><strong>The <code>/theme</code> command</strong> (recommended): opens the theme picker, where custom themes appear as <code>Custom: &lt;filename&gt;</code>. The picker <strong>re-scans the themes directory every time it opens</strong>, so a theme file you just added shows up <strong>without a restart</strong>.</p></li><li><p><strong><code>tui.toml</code></strong>: set <code>theme</code> to your theme name:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># ~/.kimi-code/tui.toml</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">theme = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ember&quot;</span></span></code></pre></div></li></ol><h2 id="what-happens-on-errors" tabindex="-1">What happens on errors <a class="header-anchor" href="#what-happens-on-errors" aria-label="Permalink to &quot;What happens on errors&quot;">​</a></h2><p>Custom themes are designed to never get in your way:</p><ul><li><strong>An invalid color value</strong> (not <code>#</code> followed by 6 hex digits): that one entry is silently skipped and falls back to the selected base palette; the rest of the colors still apply.</li><li><strong>An unrecognized token</strong>: ignored, with no effect on other colors.</li><li><strong>A missing custom theme file or malformed JSON</strong>: silently falls back to the built-in <code>dark</code> palette. It does not retry <code>auto</code>.</li></ul><h2 id="editing-the-active-theme" tabindex="-1">Editing the active theme <a class="header-anchor" href="#editing-the-active-theme" aria-label="Permalink to &quot;Editing the active theme&quot;">​</a></h2><p>If you edit the theme file that is <strong>currently active</strong>, the change is not reloaded automatically. To apply the new colors:</p><ul><li>run <code>/reload-tui</code> — it reloads <code>tui.toml</code> and re-applies the current theme (including re-reading the theme file); or</li><li>switch to another theme in <code>/theme</code> and back.</li></ul><div class="warning custom-block"><p class="custom-block-title">Note</p><p>Re-selecting the <strong>same</strong> theme in <code>/theme</code> does not reload it (you get a &quot;Theme unchanged&quot; message). To reload changes to the active theme, use one of the two methods above.</p></div>`,31)])])}const m=t(a,[["render",i]]);export{u as __pageData,m as default};
